<template>
  <div ref="study" class="access-study index-ignore" data-image-enlarge="off">
    <nav class="access-entries" :class="{ 'is-phone': device === 'phone' }" aria-label="Website entry points">
      <div v-for="(entry, index) in entryOptions" :key="entry.id" class="access-entry-slot" :class="{ 'is-hidden': device === 'phone' && index === 2 }" :inert="device === 'phone' && index === 2" :aria-hidden="device === 'phone' && index === 2">
      <div class="access-entry-clip">
      <button type="button" :aria-pressed="scene === entry.id" @click="selectEntry(entry.id)">
        <span class="access-entry-number">{{ String(index + 1).padStart(2, '0') }}</span>
        <span class="access-entry-copy"><strong>{{ entry.label }}</strong><span>{{ entry.description }}</span></span>
        <span class="access-progress" aria-hidden="true"><i :style="{ transform: `scaleX(${scene === entry.id ? elapsed / duration : 0})` }" /></span>
      </button>
      </div></div>
    </nav>
    <div class="access-film">
      <div class="access-toolbar">
        <div class="access-devices" role="group" aria-label="Preview device">
          <button v-for="option in ['desktop', 'phone']" :key="option" type="button" :aria-pressed="device === option" @click="selectDevice(option)">{{ option === 'phone' ? 'Phone' : 'Desktop' }}</button>
        </div>
        <button class="access-playback" type="button" :aria-label="finished ? 'Replay entry points' : paused ? 'Play entry points' : 'Pause entry points'" @click="togglePlayback">
          <svg viewBox="0 0 20 20" aria-hidden="true"><path v-if="finished" d="M4 7a6.5 6.5 0 1 1-.1 6M4 3v4h4"/><path v-else-if="paused" d="m7 4 8 6-8 6Z"/><path v-else d="M7 4v12M13 4v12"/></svg>
        </button>
      </div>
      <div ref="stage" class="access-stage" :class="{ 'is-changing': changing }">
        <div v-for="screen in ['desktop', 'phone']" :key="screen" class="access-window" :class="{ 'is-phone': screen === 'phone', 'is-active': device === screen }" :aria-hidden="device !== screen" :inert="device !== screen">
          <ArchiveDemoScreen :active="loaded" :compact="screen === 'phone'" :visible="visible && device === screen" :scene="scene" :state="state" :playing="playing && device === screen" :reduced-motion="reducedMotion" @ready="readyDevices[screen] = true" />
        </div>
      </div>
      <p class="access-caption">{{ caption }}</p>
    </div>
  </div>
</template>
<script>
import { demoPreloadMargin } from '../../utils/demoPreload';
import ArchiveDemoScreen from './ArchiveDemoScreen.vue';
import { archiveDemoState, DEMO_DURATION } from '../../utils/archiveDemoTimeline';
const entries = [
  { id: 'access-home', label: 'Ask on Home', description: 'Start with your question.' },
  { id: 'access-header', label: 'In the header', description: 'Open the panel on any page.' },
  { id: 'access-sidebar', label: 'While reading', description: 'Reach it as you move through a page.' },
];
export default {
  name: 'SiteAccessStudy', components: { ArchiveDemoScreen },
  data: () => ({ scene: entries[0].id, device: 'desktop', elapsed: 0, paused: false, readyDevices: { desktop: false, phone: false }, loaded: false, visible: false, pageVisible: true, changing: false, reducedMotion: false }),
  computed: {
    entryOptions() { return entries; },
    ready() { return this.readyDevices[this.device]; },
    entries() { return this.device === 'phone' ? entries.slice(0, 2) : entries; },
    duration() { return DEMO_DURATION[this.scene]; },
    state() { return archiveDemoState(this.scene, this.elapsed); },
    finished() { return this.scene === this.entries[this.entries.length - 1].id && this.elapsed >= this.duration; },
    playing() { return this.ready && this.visible && this.pageVisible && !this.paused && !this.changing && !this.finished; },
    caption() {
      if (this.scene === 'access-sidebar') return this.device === 'phone' ? 'On a phone, search stays within reach in the header.' : 'Search stays beside the page as you read.';
      return this.state.caption;
    },
  },
  watch: { playing() { this.syncClock(); } },
  mounted() {
    this._motion = matchMedia('(prefers-reduced-motion: reduce)');
    this._motionChange = () => { this.reducedMotion = this._motion.matches; if (this.reducedMotion) this.paused = true; };
    this._motionChange(); this._motion.addEventListener('change', this._motionChange);
    this._visibility = () => { this.pageVisible = !document.hidden; };
    this._visibility(); document.addEventListener('visibilitychange', this._visibility);
    this._observer = new IntersectionObserver(([entry]) => { this.visible = entry.isIntersecting && entry.intersectionRatio >= .35; }, { threshold: [0, .35] });
    this._observer.observe(this.$refs.stage);
    this._preload = new IntersectionObserver(([entry]) => { if (entry.isIntersecting) { this.loaded = true; this._preload.disconnect(); } }, { rootMargin: demoPreloadMargin() });
    this._preload.observe(this.$refs.study);
  },
  beforeUnmount() {
    cancelAnimationFrame(this._frame); clearTimeout(this._swap); clearTimeout(this._reveal);
    this._observer?.disconnect(); this._preload?.disconnect();
    this._motion?.removeEventListener('change', this._motionChange);
    document.removeEventListener('visibilitychange', this._visibility);
  },
  methods: {
    syncClock() {
      cancelAnimationFrame(this._frame);
      if (!this.playing) return;
      let last = performance.now();
      const tick = now => {
        if (!this.playing) return;
        this.elapsed = Math.min(this.duration, this.elapsed + Math.min(now - last, 80)); last = now;
        if (this.elapsed >= this.duration && !this.finished) { this.selectEntry(this.entries[this.entries.findIndex(entry => entry.id === this.scene) + 1].id); return; }
        if (!this.finished) this._frame = requestAnimationFrame(tick);
      };
      this._frame = requestAnimationFrame(tick);
    },
    selectEntry(scene) { this.changePreview(() => { this.scene = scene; this.elapsed = 0; }); },
    selectDevice(device) {
      if (this.device === device) return;
      clearTimeout(this._swap); clearTimeout(this._reveal); this.changing = false;
      this.device = device;
      if (!this.entries.some(entry => entry.id === this.scene)) this.scene = 'access-header';
      this.elapsed = 0; this.paused = this.reducedMotion;
    },
    changePreview(change) {
      clearTimeout(this._swap); clearTimeout(this._reveal); this.changing = true;
      this._swap = setTimeout(() => {
        change(); this.paused = this.reducedMotion;
        this._reveal = setTimeout(() => { this.changing = false; }, this.reducedMotion ? 0 : 300);
      }, this.reducedMotion ? 0 : 160);
    },
    togglePlayback() { if (this.finished) this.selectEntry(entries[0].id); else this.paused = !this.paused; },
  },
};
</script>
